const body = $json.body ?? $json;
const first = (...values) => values.find(v => v !== undefined && v !== null && String(v).trim() !== '') ?? '';
const phoneRaw = first(body.phone, body.customer_phone, body.caller_phone, body.from);
const phone = String(phoneRaw).replace(/[()\\s.-]/g, '');
const urgencyRaw = String(first(body.urgency, body.priority, 'normal')).toLowerCase();
const urgentTerms = ['emergency','urgent','no heat','no cooling','gas smell','carbon monoxide','co alarm','sparking','smoke'];
const summary = String(first(body.summary, body.call_summary, body.transcript_summary, body.issue, body.reason));
const urgency = urgentTerms.some(term => `${urgencyRaw} ${summary.toLowerCase()}`.includes(term)) ? 'urgent' : urgencyRaw;
const consent = first(body.consent_to_text, body.sms_consent, false);
return [{json:{event_type:'hvac_ai_receptionist_lead',call_id:first(body.call_id,body.id,''),customer_name:String(first(body.customer_name,body.name,body.caller_name,'')),phone,service_address:String(first(body.service_address,body.address,'')),city:String(first(body.city,'')),state:String(first(body.state,'')),zip_code:String(first(body.zip_code,body.zip,'')),issue_type:String(first(body.issue_type,body.issue,body.reason,'')),summary,urgency,preferred_time:String(first(body.preferred_time,body.time_preference,'')),booking_status:String(first(body.booking_status,'not_booked')),consent_to_text:consent===true||String(consent).toLowerCase()==='true'||String(consent)==='yes',received_at:new Date().toISOString(),phone_present:phone.length>=7}}];
